package com.cybershield.controller;
import com.cybershield.dto.*; import com.cybershield.model.*; import com.cybershield.repository.UserRepository; import com.cybershield.security.JwtService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/auth") public class AuthController { final UserRepository users; final PasswordEncoder enc; final JwtService jwt; public AuthController(UserRepository u,PasswordEncoder e,JwtService j){users=u;enc=e;jwt=j;} @PostMapping("/login") public ResponseEntity<?> login(@Valid @RequestBody AuthRequest r){var u=users.findByEmail(r.email()).orElse(null);if(u==null||!u.isActive()||!enc.matches(r.password(),u.getPassword()))return ResponseEntity.status(401).body(Map.of("message","Invalid email or password"));return ResponseEntity.ok(Map.of("token",jwt.generate(u.getEmail(),u.getRole().name()),"user",Map.of("id",u.getId(),"name",u.getName(),"email",u.getEmail(),"role",u.getRole().name())));} @PostMapping("/register") public ResponseEntity<?> register(@Valid @RequestBody RegisterRequest r){if(users.findByEmail(r.email()).isPresent())return ResponseEntity.badRequest().body(Map.of("message","Email already registered"));User u=new User();u.setName(r.name());u.setEmail(r.email());u.setPassword(enc.encode(r.password()));u.setRole(Role.USER);users.save(u);return ResponseEntity.status(HttpStatus.CREATED).body(Map.of("message","Registration successful. Please login."));} }
